1) We have
\begin{align*}
a_{n+1} &= a_n - \frac{1}{1+\sum_{i=1}^n\frac{1}{a_i}} \\
&= a_n - \frac{1}{1+\frac{1}{a_1}+\frac{1}{a_2}+\ldots+\frac{1}{a_n}} \\
&= a_n - \frac{a_1a_2\ldots a_n}{a_1a_2\ldots a_n + a_1 + a_2 + \ldots + a_n} \\
&= a_n - \frac{a_1a_2\ldots a_n}{(a_1+1)(a_2+1)\ldots(a_n+1)} \\
&= \frac{a_1a_2\ldots a_n}{(a_1+1)(a_2+1)\ldots(a_n+1)}.
\end{align*}
Thus, we can write
\begin{align*}
\frac{1}{a_{n+1}} &= \frac{(a_1+1)(a_2+1)\ldots(a_n+1)}{a_1a_2\ldots a_n} \\
&= \left(1+\frac{1}{a_1}\right)\left(1+\frac{1}{a_2}\right)\ldots\left(1+\frac{1}{a_n}\right) \\
&= 1 + \frac{1}{a_1} + \frac{1}{a_2} + \ldots + \frac{1}{a_n} + \ldots + \frac{1}{a_1a_2\ldots a_n}.
\end{align*}
Therefore,
\begin{align*}
\frac{1}{a_{n+1}} - \frac{1}{a_n} &= 1 + \frac{1}{a_1} + \frac{1}{a_2} + \ldots + \frac{1}{a_{n-1}} + \frac{1}{a_1a_2\ldots a_{n-1}} \\
&= \frac{1}{a_1} + \frac{1}{a_2} + \ldots + \frac{1}{a_{n-1}} + \frac{1}{a_1a_2\ldots a_{n-1}}.
\end{align*}
Similarly, we can derive that
\begin{align*}
\frac{1}{b_{n+1}} - \frac{1}{b_n} &= \frac{1}{b_1} + \frac{1}{b_2} + \ldots + \frac{1}{b_{n-1}} + \frac{1}{b_1b_2\ldots b_{n-1}}.
\end{align*}
Subtracting the two equations, we get
\begin{align*}
\frac{1}{a_{n+1}} - \frac{1}{b_{n+1}} &= \left(\frac{1}{a_1} - \frac{1}{b_1}\right) + \left(\frac{1}{a_2} - \frac{1}{b_2}\right) + \ldots + \left(\frac{1}{a_n} - \frac{1}{b_n}\right) \\
&\quad + \left(\frac{1}{a_1a_2\ldots a_n} - \frac{1}{b_1b_2\ldots b_n}\right).
\end{align*}
Given that $a_{100}b_{100} = a_{101}b_{101}$, we have
\begin{align*}
\frac{1}{a_{101}} - \frac{1}{b_{101}} &= \left(\frac{1}{a_1} - \frac{1}{b_1}\right) + \left(\frac{1}{a_2} - \frac{1}{b_2}\right) + \ldots + \left(\frac{1}{a_{100}} - \frac{1}{b_{100}}\right) \\
&\quad + \left(\frac{1}{a_1a_2\ldots a_{100}} - \frac{1}{b_1b_2\ldots b_{100}}\right) = 0.
\end{align*}
Therefore, we conclude that
\begin{align*}
\frac{1}{a_1} - \frac{1}{b_1} &= \frac{1}{a_2} - \frac{1}{b_2} = \ldots = \frac{1}{a_{100}} - \frac{1}{b_{100}} = 0,
\end{align*}
which implies that $a_1 = b_1$. Hence, the value of $a_1 - b_1$ is $\boxed{0}$.

2) We have
\begin{align*}
a_{n+1} + b_{n+1} &= a_n + b_n - \frac{1}{1+\sum_{i=1}^n\frac{1}{a_i}} + \frac{1}{1+\sum_{i=1}^n\frac{1}{b_i}} \\
&= a_n + b_n - \frac{b_1b_2\ldots b_n - a_1a_2\ldots a_n}{(a_1+1)(a_2+1)\ldots(a_n+1)(b_1+1)(b_2+1)\ldots(b_n+1)}.
\end{align*}
Given that $a_{100} = b_{99}$, we have
\begin{align*}
a_{100} + b_{100} - a_{101} - b_{101} &= \frac{b_1b_2\ldots b_{99} - a_1a_2\ldots a_{99}}{(a_1+1)(a_2+1)\ldots(a_{99}+1)(b_1+1)(b_2+1)\ldots(b_{99}+1)} \\
&= \frac{b_1b_2\ldots b_{98}(b_{99} - a_{99})}{(a_1+1)(a_2+1)\ldots(a_{99}+1)(b_1+1)(b_2+1)\ldots(b_{99}+1)}.
\end{align*}
Since $a_{100} = b_{99}$, we have $b_{99} - a_{99} = a_{100} - a_{99} > 0$. Therefore, $a_{100} + b_{100} - a_{101} - b_{101} > 0$, which implies that $a_{100} + b_{100} > a_{101} + b_{101}$. Hence, the value of $a_{100} + b_{100}$ is larger than $a_{101} + b_{101}$, and the answer is $\boxed{a_{100} + b_{100}}$.

